styles.css:
/* Prism YouTube module */

/* ===== Logo: hide defaults when our logo is active ===== */
html.prism-logoMode-text ytd-topbar-logo-renderer #logo-icon,
html.prism-logoMode-image ytd-topbar-logo-renderer #logo-icon,
html.prism-logoMode-preset ytd-topbar-logo-renderer #logo-icon,
html.prism-logoMode-hidden ytd-topbar-logo-renderer #logo-icon,
html.prism-logoMode-random ytd-topbar-logo-renderer #logo-icon { display: none !important; }

html.prism-on-yoodleOverride.prism-logoMode-text ytd-yoodle-renderer,
html.prism-on-yoodleOverride.prism-logoMode-image ytd-yoodle-renderer,
html.prism-on-yoodleOverride.prism-logoMode-preset ytd-yoodle-renderer,
html.prism-on-yoodleOverride.prism-logoMode-hidden ytd-yoodle-renderer,
html.prism-on-yoodleOverride.prism-logoMode-random ytd-yoodle-renderer { display: none !important; }

html.prism-logoMode-hidden ytd-topbar-logo-renderer #logo { visibility: hidden !important; }
html.prism-on-hideCountryCode ytd-topbar-logo-renderer #country-code { display: none !important; }

/* The injected logo container */
.prism-yt-logo {
  display: inline-flex;
  align-items: center;
  gap: 0;
  height: 20px;
  text-decoration: none;
  transform: scale(calc(var(--prism-logoScale, 100) / 100));
  transform-origin: left center;
  user-select: none;
  font-family: 'YouTube Sans', 'Inter', -apple-system, 'Segoe UI', Roboto, sans-serif;
}
.prism-yt-logo .prism-yt-text { font-size: 18px; font-weight: 700; letter-spacing: -0.5px; line-height: 1; color: var(--prism-logoColor, #fff); }
.prism-yt-logo .prism-yt-play { display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 20px; background: #ff0033; border-radius: 4px; margin-right: 4px; color: #fff; font-size: 13px; font-weight: 900; padding-bottom: 1px; }
html.prism-logoFont-bold .prism-yt-text { font-family: Arial, Helvetica, sans-serif; font-weight: 900; letter-spacing: 0; }
html.prism-logoFont-mono .prism-yt-text { font-family: 'JetBrains Mono', ui-monospace, Menlo, monospace; font-weight: 700; letter-spacing: 0; }
html.prism-logoFont-serif .prism-yt-text { font-family: Georgia, 'Times New Roman', serif; font-weight: 700; }
html.prism-logoFont-caps .prism-yt-text { font-family: 'Arial Narrow', Impact, sans-serif; font-weight: 900; text-transform: uppercase; letter-spacing: 1px; font-size: 16px; }
html.prism-on-logoGlow .prism-yt-text { text-shadow: 0 0 6px currentColor, 0 0 14px currentColor; }

/* Retro presets */
.prism-yt-preset-classic2005 .prism-yt-text { font-family: 'Arial Narrow', Impact, sans-serif; font-weight: 900; font-size: 17px; color: #fff; letter-spacing: 0.5px; }
.prism-yt-preset-classic2005 .prism-yt-play { background: #cc181e; border-radius: 6px; width: 32px; height: 22px; }
.prism-yt-preset-wordmark2011 .prism-yt-text { font-family: 'YouTube Sans', Arial, sans-serif; font-weight: 500; font-size: 19px; letter-spacing: -1px; }
.prism-yt-preset-neon .prism-yt-text { color: #0ff; text-shadow: 0 0 4px #0ff, 0 0 10px #0ff, 0 0 18px #f0f; font-family: 'JetBrains Mono', monospace; font-weight: 700; }
.prism-yt-preset-neon .prism-yt-play { background: transparent; box-shadow: 0 0 8px #f0f, 0 0 16px #f0f; border: 1px solid #f0f; color: #f0f; }
.prism-yt-preset-vaporwave .prism-yt-text { color: #ff71ce; text-shadow: 2px 2px 0 #01cdfe, -2px -2px 0 #b967ff; font-family: 'Arial Narrow', sans-serif; font-weight: 900; font-style: italic; }
.prism-yt-preset-vaporwave .prism-yt-play { background: linear-gradient(135deg, #ff71ce, #01cdfe); }
.prism-yt-preset-terminal .prism-yt-text { color: #00ff41; font-family: 'JetBrains Mono', monospace; text-shadow: 0 0 6px #00ff41; }
.prism-yt-preset-terminal .prism-yt-play { background: #00ff41; color: #000; }
.prism-yt-preset-gold .prism-yt-text { color: #e7b458; }
.prism-yt-preset-gold .prism-yt-play { background: linear-gradient(135deg, #e7b458, #b3822f); color: #1a1208; }

/* ===== Player accent ===== */
html.prism-mod-youtube .ytp-play-progress { background-color: var(--prism-accentColor, #ff0033) !important; }
html.prism-mod-youtube .ytp-swatch-background-color { background-color: var(--prism-accentColor, #ff0033) !important; }
html.prism-mod-youtube .ytp-slider-handle { background-color: var(--prism-accentColor, #ff0033) !important; }

/* ===== Rainbow progress bar ===== */
html.prism-on-rainbowProgress .ytp-play-progress {
  background: linear-gradient(90deg, #ff0040, #ff8c00, #ffd700, #00e676, #00b0ff, #7c4dff, #e040fb) !important;
  background-size: 200% 100% !important;
  animation: prism-rainbow-progress 3s linear infinite !important;
}
@keyframes prism-rainbow-progress { 0% { background-position: 0% 50%; } 100% { background-position: 200% 50%; } }

/* ===== Thicker progress bar ===== */
html.prism-on-thickProgress .ytp-progress-bar { height: 8px !important; }
html.prism-on-thickProgress .ytp-progress-bar:hover { height: 12px !important; }

/* ===== CRT scanline mode ===== */
html.prism-on-crtMode #movie_player { filter: contrast(1.12) saturate(0.85) brightness(0.95); }
html.prism-on-crtMode #movie_player::after {
  content: '';
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(0deg, rgba(0,0,0,0.18) 0, rgba(0,0,0,0.18) 1px, transparent 1px, transparent 3px);
  pointer-events: none;
  z-index: 9999;
  mix-blend-mode: multiply;
}
html.prism-on-crtMode #movie_player::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, transparent 60%, rgba(0,0,0,0.5) 100%);
  pointer-events: none;
  z-index: 9998;
}

/* ===== Vaporwave filter ===== */
html.prism-on-vaporwaveMode #movie_player { filter: hue-rotate(290deg) saturate(1.6) contrast(1.15); }
html.prism-on-vaporwaveMode #movie_player::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent, rgba(255, 113, 206, 0.16), rgba(1, 205, 254, 0.12));
  pointer-events: none;
  z-index: 9999;
}

/* ===== Konami / party mode ===== */
html.prism-party body { animation: prism-party-hue 4s linear infinite; }
@keyframes prism-party-hue { 0% { filter: hue-rotate(0deg); } 100% { filter: hue-rotate(360deg); } }

/* ===== Prism toast ===== */
#prism-toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: rgba(20, 20, 26, 0.96);
  color: #f4f2ee;
  padding: 12px 18px;
  border-radius: 12px;
  font-family: -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.2px;
  border: 1px solid rgba(231, 180, 88, 0.4);
  box-shadow: 0 8px 32px rgba(0,0,0,0.4), 0 0 0 1px rgba(255,255,255,0.05);
  z-index: 999999;
  opacity: 0;
  transition: opacity 0.25s, transform 0.25s;
  pointer-events: none;
}
#prism-toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
#prism-toast .prism-toast-accent { color: #e7b458; font-weight: 700; }
